def byte_at(node, index):
    """The byte at ``index`` of a rope."""
    if node is None or index < 0 or index >= node.length:
        raise ValueError('byte index')
    while True:
        if node.kind == Leaf.kind:
            return node.data[index]
        if node.kind == Rep.kind:
            unit = node.child.length
            index %= unit
            node = node.child
        else:
            if index < node.left.length:
                node = node.left
            else:
                index -= node.left.length
                node = node.right
